bits 64
global _start ; define entry point

; declares uninitialized static variables
section .bss
    buf: resb 2 ; buffer for storing a value in hexadecimal format

; contains executable instructions
section .text
	_start: ; entry point
		; display the source code prefix stored in the source data variable
		mov rsi, source_data
		mov edx, SOURCE_DATA_LEN-37
		call _print

		; stores the data tables in the registers
		lea rbx, [source_data]
		lea r8, [hex_table]
		_loop: ; loop that reads each character stored in the rbx register to print it in hexadecimal format
			movzx eax, byte [rbx]

			; Separate the high-order and low-order bytes in the EAX and ECX registers
			mov ecx, eax
			shr eax, 4
			and ecx, 0x0f

			; Store the values of the RAX and RCX registers in the buffer in hexadecimal format
			mov al, [r8 + rax]
			mov cl, [r8 + rcx]
			mov [buf], al
			mov [buf+1], cl

			; print the type for the array
			mov rsi, hexa
			mov edx, 2
			call _print

			; print the contents of the hexadecimal buffer
			mov rsi, buf
			mov edx, 2
			call _print

			; increments the loop up to the last character, and exits if the end of the string is reached
			inc rbx
			cmp byte [rbx], 0
			je _end

			; print the comma to separate the hexadecimal values
			mov rsi, comma
			mov edx, 2
			call _print

			; loop
			jmp _loop

		_print: ; Function called to display the contents of the RSI register on standard output
			mov eax, 1
			mov edi, 1
			syscall
			ret ; ret is used to exit a procedure and transfer control to the caller

		_end: ; _end is called to display the source_data suffix and exit the program cleanly
			mov rsi, SOURCE_DATA_LEN+source_data-37
			mov edx, 37
			call _print
			
			mov rax, 60
			xor rdi, rdi
			syscall

